#!/bin/bash
cd "$(dirname "$0")/../../.."
O=var/handover-06/out
st(){ for f in var/datastores/handover-06-*.sqlite; do printf '%s  %s\n' "$(shasum -a 256 $f | cut -c1-64)" "$(/usr/bin/stat -f '%m %z %N' $f)"; done; ls var/datastores | grep -E -- '-journal|-wal|-shm' | sed 's/^/JOURNAL /'; }
before=$(st); echo "$before" > var/handover-06/state/store_files_before_checks.txt
PYTHONPATH=. ./venv/bin/python docs/a3-v2-readiness/rehearsal/closed_store_state.py var/datastores/handover-06-resumed.sqlite > var/handover-06/state/after-resumed-c.txt 2>&1
{ echo "== after resumed-c: \$ PYTHONPATH=. ./venv/bin/python docs/a3-v2-readiness/rehearsal/closed_store_state.py <store>   (also var/handover-06/state/after-resumed-c.txt)"; cat var/handover-06/state/after-resumed-c.txt; echo; } >> $O/closed_store_state_06.txt
for s in a b; do { echo "== $(date +%H:%M:%S) prune_check after resumed-c, against the state after resumed-$s"; echo "\$ ./venv/bin/python docs/dk-and-rpk-migration/rehearsal/prune_check.py var/handover-06/state/after-resumed-$s.txt var/datastores/handover-06-resumed.sqlite"; ./venv/bin/python docs/dk-and-rpk-migration/rehearsal/prune_check.py var/handover-06/state/after-resumed-$s.txt var/datastores/handover-06-resumed.sqlite; echo "rc=$?"; echo; } >> $O/prune_check_06.txt 2>&1; done
{ echo '$ PYTHONPATH=. ./venv/bin/python docs/datastore-integrity-verification/compare_stores.py var/datastores/handover-06-reference.sqlite var/datastores/handover-06-resumed.sqlite'; PYTHONPATH=. ./venv/bin/python docs/datastore-integrity-verification/compare_stores.py var/datastores/handover-06-reference.sqlite var/datastores/handover-06-resumed.sqlite; echo "rc=$?"; } > $O/fingerprint_comparison_06.txt 2>&1
A="var/handover-06/recorded/rrk-v020-adoption-03-reference-20261018T232838 var/handover-06/recorded/rrk-v020-adoption-03-resumed-c-20261018T233941"
{ echo "\$ PYTHONPATH=. ./venv/bin/python docs/dk-and-rpk-migration/rehearsal/compare_with_recorded.py var/datastores/handover-06-reference.sqlite var/datastores/handover-06-resumed.sqlite --against $A"; PYTHONPATH=. ./venv/bin/python docs/dk-and-rpk-migration/rehearsal/compare_with_recorded.py var/datastores/handover-06-reference.sqlite var/datastores/handover-06-resumed.sqlite --against $A; echo "rc=$?"; } > $O/fingerprint_against_recorded_06.txt 2>&1
{ echo '$ PYTHONPATH=. ./venv/bin/python docs/datastore-integrity-audit/replicated_serial_census.py var/datastores/handover-06-reference.sqlite var/datastores/handover-06-resumed.sqlite'; PYTHONPATH=. ./venv/bin/python docs/datastore-integrity-audit/replicated_serial_census.py var/datastores/handover-06-reference.sqlite var/datastores/handover-06-resumed.sqlite; echo "rc=$?"; } > $O/census_06.txt 2>&1
{ echo '$ PYTHONPATH=. ./venv/bin/python docs/dk-and-rpk-migration/rehearsal/store_soundness.py var/datastores/handover-06-reference.sqlite var/datastores/handover-06-resumed.sqlite'; PYTHONPATH=. ./venv/bin/python docs/dk-and-rpk-migration/rehearsal/store_soundness.py var/datastores/handover-06-reference.sqlite var/datastores/handover-06-resumed.sqlite; echo "rc=$?"; } > $O/store_soundness_06.txt 2>&1
after=$(st); echo "$after" > var/handover-06/state/store_files_after_checks.txt
if [ "$before" = "$after" ]; then echo "STORE FILES: identical before and after the checks (SHA-256, mtime, size); no journal"; else echo "STORE FILES CHANGED"; diff <(echo "$before") <(echo "$after"); fi
